# Transcription of the three Dragon monsters (owner scans 2026-11-19). Writes docs/transcriptions/<id>_raw.json.
# Icons: [V]=Vigor, [H]=Heat, [P]=Passion, [Peril]=Peril Check, [Armor]=Armor token, [Gear]=Gear card, [die]=Evasion die, [React]=REACT! window, [AT]=Armor Toughness.
# Gates are written "{P4+: BANE 2 INSTEAD}". Engine support for these monsters is NOT implemented yet.
import json, os
OUT = os.path.join(os.path.dirname(__file__), '..', '..', 'docs', 'transcriptions')
def A(name, lv, typ, dice, diff, tg, tag, eff, after=None, afterTag='AFTER ATTACK', pre=None, zone=None, unclear=None):
    return dict(name=name, level=lv, type=typ, evasionDice=dice, evasionDifficulty=diff, pre=pre, targeting=tg, tag=tag, effects=eff, afterTag=afterTag if after else None, after=after, zone=zone, unclear=unclear or [])
def B(name, lv, at, top=None, u=None, i=None, w=None, f=None, c=None, note=None, unclear=None):
    return dict(name=name, level=lv, at=at, top=top, note=note, ultrainstinct=u, instinct=i, wound=w, fail=f, critical=c, unclear=unclear or [])
def L(toHit, wounds, exh, acts, esc=0, at=0, traits=()):
    return dict(toHit=toHit, wounds=wounds, exhibitionWounds=exh, activations=acts, traitsAdd=list(traits), bonuses=dict(escalations=esc, at=at, vigorLoss=0, evasionDice=0, heat=0))
T = lambda n, lv, t: dict(name=n, level=lv, text=t)
FF = ['Furthest Knight in front', 'Furthest Knight in sight']; TURN = 'turns to face the most Knights.'
PT = '[Priority Target] Priority Target'; DT = '[Divine Target] Divine Target'
DF = 'Additional Setup: Add the Your Death Becomes a Dragon\'s Sacrament Judicium card to the Judicium deck.'
VPC = 'Create a Vantage Point. If the VP is already in play and you are adjacent to the {}, you may climb it.'

